void func_8012DD00(GameObject *o)
{
    switch (o->state) {
    case 0:
        if (GAME.selectedSection == 1) {
            o->y.raw = -0xea;
        } else if (GAME.purifiedAreas & 0x40) {
            o->y.raw = -0x50;
        } else {
            o->y.raw = -0x3b8;
        }
        (*(GVars_2DD00 *)&D_8009BC98).s44 = 0;
        (*(GVars_2DD00 *)&D_8009BC98).s46 = -0x40;
        o->state++;
        break;
    case 1: {
        GameObject *p = &(*(GameObject *)&PLAYER);
        switch ((*(GameObject *)&PLAYER).subState) {
        case 0x3e:
            if ((*(GameObject *)&PLAYER).y.p.whole < o->y.raw) {
                (*(GameObject *)&PLAYER).y.p.whole = o->y.raw;
                { s32 y = o->y.raw;
                (*(GameObject *)&PLAYER).subState = 0x3d;
                (*(GameObject *)&PLAYER).step = 0;
                (*(GameObject *)&PLAYER).unk78 = y; }
            }
            break;
        case 2:
        case 0xd:
            if (o->y.raw < p->y.p.whole) {
                p->y.p.whole = o->y.raw;
                { s32 y = o->y.raw;
                p->subState = 0x3d;
                p->step = 0;
                p->unk78 = y; }
            }
            break;
        }
        break;
    }
    case 2:
        o->state = 3;
        break;
    case 3:
        freeObjectUnlayered(o);
        break;
    }
}

